CREATE TYPE "PlatformGraphNodeType" AS ENUM ('DOMAIN','SERVICE','MODULE','API','ROUTE','DATABASE','TABLE','COLUMN','EVENT','QUEUE','JOB','CACHE','SEARCH_INDEX','PROVIDER','EXTERNAL_SYSTEM','FEATURE_FLAG','WORKFLOW','CUSTOMER_JOURNEY','INCIDENT','SLO','ALERT','AUTOMATION','REMEDIATION','RESILIENCE_EXPERIMENT','DIGITAL_TWIN_SCENARIO','GOVERNANCE_CONTROL','RECONCILIATION_RULE','MIGRATION','DEPENDENCY','DEPLOYMENT','OWNER','DOCUMENT','ADR');
CREATE TYPE "PlatformGraphRelationType" AS ENUM ('OWNS','CONTAINS','DEPENDS_ON','CALLS','READS','WRITES','PUBLISHES','CONSUMES','TRIGGERS','PROTECTS','MONITORS','ALERTS_ON','IMPLEMENTS','FULFILLS','USES','CONTROLS','FLAGS','VALIDATES','RECONCILES','MIGRATES','DEPLOYS','AFFECTS','IMPACTS','DOCUMENTS','GOVERNED_BY','TESTED_BY','RECOVERS_WITH','ROLLS_BACK_WITH');
CREATE TYPE "PlatformGraphProvenance" AS ENUM ('CODE','DATABASE_SCHEMA','API_CONTRACT','CONFIGURATION','DEPLOYMENT','DOCUMENTATION','OBSERVABILITY','RUNTIME_TELEMETRY','CI','TEST','GOVERNANCE_RECORD','MANUAL_REVIEW','IMPORTED_METADATA');
CREATE TYPE "PlatformGraphConfidence" AS ENUM ('UNKNOWN','LOW','MEDIUM','HIGH','VERIFIED');
CREATE TYPE "PlatformGraphFreshness" AS ENUM ('CURRENT','AGING','STALE','UNKNOWN');
CREATE TYPE "PlatformGraphDriftSeverity" AS ENUM ('INFO','LOW','MEDIUM','HIGH','CRITICAL');
CREATE TABLE "PlatformGraphNode" ("id" UUID NOT NULL,"stableId" VARCHAR(200) NOT NULL,"type" "PlatformGraphNodeType" NOT NULL,"name" VARCHAR(240) NOT NULL,"sourceOfTruth" VARCHAR(240),"owner" VARCHAR(160),"environment" VARCHAR(80),"status" VARCHAR(80),"confidence" "PlatformGraphConfidence" NOT NULL DEFAULT 'UNKNOWN',"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlatformGraphNode_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlatformGraphRelationship" ("id" UUID NOT NULL,"stableId" VARCHAR(240) NOT NULL,"fromNodeId" UUID NOT NULL,"toNodeId" UUID NOT NULL,"relationType" "PlatformGraphRelationType" NOT NULL,"provenance" "PlatformGraphProvenance" NOT NULL,"sourceIdentifier" VARCHAR(500) NOT NULL,"confidence" "PlatformGraphConfidence" NOT NULL DEFAULT 'UNKNOWN',"verifier" VARCHAR(160),"discoveredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastVerifiedAt" TIMESTAMP(3),"lastObservedAt" TIMESTAMP(3),"staleThresholdSeconds" INTEGER NOT NULL DEFAULT 86400,"freshness" "PlatformGraphFreshness" NOT NULL DEFAULT 'UNKNOWN',"version" INTEGER NOT NULL DEFAULT 1,"active" BOOLEAN NOT NULL DEFAULT true,"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlatformGraphRelationship_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlatformGraphEvidence" ("id" UUID NOT NULL,"relationshipId" UUID NOT NULL,"provenance" "PlatformGraphProvenance" NOT NULL,"sourceIdentifier" VARCHAR(500) NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"summary" VARCHAR(2000) NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"payload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlatformGraphEvidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlatformGraphFinding" ("id" UUID NOT NULL,"kind" VARCHAR(100) NOT NULL,"severity" "PlatformGraphDriftSeverity" NOT NULL,"scope" VARCHAR(300) NOT NULL,"details" JSONB NOT NULL,"methodologyVersion" VARCHAR(40) NOT NULL,"status" VARCHAR(32) NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlatformGraphFinding_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PlatformGraphNode_stableId_key" ON "PlatformGraphNode"("stableId");
CREATE INDEX "PlatformGraphNode_type_name_idx" ON "PlatformGraphNode"("type","name");
CREATE INDEX "PlatformGraphNode_owner_type_idx" ON "PlatformGraphNode"("owner","type");
CREATE UNIQUE INDEX "PlatformGraphRelationship_stableId_key" ON "PlatformGraphRelationship"("stableId");
CREATE INDEX "PlatformGraphRelationship_fromNodeId_relationType_active_idx" ON "PlatformGraphRelationship"("fromNodeId","relationType","active");
CREATE INDEX "PlatformGraphRelationship_toNodeId_relationType_active_idx" ON "PlatformGraphRelationship"("toNodeId","relationType","active");
CREATE INDEX "PlatformGraphRelationship_freshness_active_idx" ON "PlatformGraphRelationship"("freshness","active");
CREATE INDEX "PlatformGraphRelationship_sourceIdentifier_version_idx" ON "PlatformGraphRelationship"("sourceIdentifier","version");
CREATE INDEX "PlatformGraphEvidence_relationshipId_observedAt_idx" ON "PlatformGraphEvidence"("relationshipId","observedAt");
CREATE INDEX "PlatformGraphEvidence_sourceIdentifier_observedAt_idx" ON "PlatformGraphEvidence"("sourceIdentifier","observedAt");
CREATE INDEX "PlatformGraphFinding_status_severity_createdAt_idx" ON "PlatformGraphFinding"("status","severity","createdAt");
CREATE INDEX "PlatformGraphFinding_kind_scope_idx" ON "PlatformGraphFinding"("kind","scope");
ALTER TABLE "PlatformGraphRelationship" ADD CONSTRAINT "PlatformGraphRelationship_fromNodeId_fkey" FOREIGN KEY ("fromNodeId") REFERENCES "PlatformGraphNode"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PlatformGraphRelationship" ADD CONSTRAINT "PlatformGraphRelationship_toNodeId_fkey" FOREIGN KEY ("toNodeId") REFERENCES "PlatformGraphNode"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PlatformGraphEvidence" ADD CONSTRAINT "PlatformGraphEvidence_relationshipId_fkey" FOREIGN KEY ("relationshipId") REFERENCES "PlatformGraphRelationship"("id") ON DELETE RESTRICT ON UPDATE CASCADE;